import { useAuthState } from 'react-firebase-hooks/auth';
import { useCollectionData } from 'react-firebase-hooks/firestore';

import { initializeApp } from "firebase/app";

const firebaseConfig = {
  apiKey: "AIzaSyC-faolhhaTx3b4s8sbSEpBTLVMSB04Upg",
  authDomain: "mypuzzlediary.firebaseapp.com",
  projectId: "mypuzzlediary",
  storageBucket: "mypuzzlediary.appspot.com",
  messagingSenderId: "325620729234",
  appId: "1:325620729234:web:a03097ec332f2283f42d4b"
};
// Initialize Firebase
const app = initializeApp(firebaseConfig);

const auth = firebase.auth();
const [user] = useAuthState(auth);



function App() {
  return (
    <div className="App">
        <header>

        </header>
        <div>
          { user ? <Board /> : <SignIn /> }
        </div>
    </div>
  );
}

function SignIn() {
  return (
    <button>Sign in with Google</button>
  );
}

export default App;
